7	Test test_a2_local_mix("a2.local.mix", []() {
8		RNG rng(2266524198);
9	
10		Halfedge_Mesh mesh = Halfedge_Mesh::from_indexed_mesh(Util::closed_sphere_mesh(1.0f, 2));
11	
12		constexpr uint32_t operations = 10;
13	
14		// On a list iterator, std::advance is O(n), making this O(n^2).
15		// It would be nice if we had a halfedge mesh implementation with flat arrays instead of std::lists...
16		auto vertex = [&]() {
17			int32_t idx = rng.integer(0, static_cast<int32_t>(mesh.vertices.size()));
18			auto itr = mesh.vertices.begin();
19			std::advance(itr, idx);
20			return itr;
21		};
22		auto edge = [&]() {
23			int32_t idx = rng.integer(0, static_cast<int32_t>(mesh.edges.size()));
24			auto itr = mesh.edges.begin();
25			std::advance(itr, idx);
26			return itr;
27		};
28		auto face = [&]() {
29			int32_t idx = rng.integer(0, static_cast<int32_t>(mesh.faces.size()));
30			auto itr = mesh.faces.begin();
31			std::advance(itr, idx);
32			return itr;
33		};
34	
35	    auto positions = [&](Halfedge_Mesh::FaceRef f) {
36			Halfedge_Mesh::HalfedgeRef face_he = f->halfedge;
37			Halfedge_Mesh::HalfedgeRef face_he_orig = face_he;
38	        std::vector<Vec3> start_positions;
39			do {
40	            start_positions.push_back(face_he->vertex->position);
41				face_he = face_he->next;
42			} while (face_he != face_he_orig);
43	        return start_positions;
44	    };
45	
46		for (uint32_t i = 0; i < operations; i++) {
47			int32_t op = rng.integer(0, 11);
48			switch (op) {
49			case 0: {
50				auto e = edge();
51				mesh.split_edge(e);
52			} break;
53			case 1: {
54				auto e = edge();
55				mesh.flip_edge(e);
56			} break;
57			case 2: {
58				auto e = edge();
59				mesh.collapse_edge(e);
60			} break;
61			case 3: {
62				auto f = face();
63				if(auto ret = mesh.extrude_face(f)) {
64	                mesh.extrude_positions(ret.value(), ret.value()->normal(), 0.5f);
65	            }
66			} break;
67			case 4: {
68				auto e = edge();
69				mesh.dissolve_edge(e);
70			} break;
71			case 5: {
72				auto f = face();
73				mesh.collapse_face(f);
74			} break;
75			case 6: {
76				auto f = face();
77				mesh.inset_vertex(f);
78			} break;
79			case 7: {
80				auto e = edge();
81				mesh.bisect_edge(e);
82			} break;
83			case 8: {
84				auto v = vertex();
85				if(auto ret = mesh.bevel_vertex(v)) {
86	                mesh.bevel_positions(ret.value(), positions(ret.value()), ret.value()->normal(), 0.5f);
87	            }
88			} break;
89			case 9: {
90				auto v = vertex();
91				mesh.dissolve_vertex(v);
92			} break;
93			case 10: {
94				auto e = edge();
95				if(auto ret = mesh.bevel_edge(e)) {
96	                mesh.bevel_positions(ret.value(), positions(ret.value()), ret.value()->normal(), 0.5f);
97	            }
98			} break;
99			default: die("Got bad random operation?");
100			}
101	
102			if (auto msg = mesh.validate()) {
103				throw Test::error("Invalid mesh after operation " + std::to_string(op) + " with seed " +
104				                  std::to_string(rng.get_seed()) + ": " + msg.value().second);
105			}
106		}
107	});
