366	//helper used to get set of pointers into a list (used by validate and describe):
367	template< typename T >
368	static std::unordered_set< T const * > element_addresses(std::list< T > const &list) {
369		std::unordered_set< T const * > address_set;
370		for (auto const &e : list) {
371			auto ret = address_set.emplace(&e);
372			assert(ret.second);
373		}
374		return address_set;
375	}
