447	std::optional<std::pair<Halfedge_Mesh::ElementCRef, std::string>> Halfedge_Mesh::validate() const {
448	
449		//helpers for error messages:
450		auto describe_vertex   = [](VertexCRef v)   { return "Vertex with id " + std::to_string(v->id); };
451		auto describe_edge     = [](EdgeCRef e)     { return "Edge with id " + std::to_string(e->id); };
452		auto describe_face     = [](FaceCRef f)     { return "Face with id " + std::to_string(f->id); };
453		auto describe_halfedge = [](HalfedgeCRef h) { return "Halfedge with id " + std::to_string(h->id); };
454	
455	
456		//-----------------------------
457		//check element data:
458		for (VertexCRef v = vertices.begin(); v != vertices.end(); ++v) {
459			if (!std::isfinite(v->position.x)) return {{v, describe_vertex(v) + " has position.x set to a non-finite value: " + std::to_string(v->position.x) + "."}};
460			if (!std::isfinite(v->position.y)) return {{v, describe_vertex(v) + " has position.y set to a non-finite value: " + std::to_string(v->position.y) + "."}};
461			if (!std::isfinite(v->position.z)) return {{v, describe_vertex(v) + " has position.z set to a non-finite value: " + std::to_string(v->position.z) + "."}};
462			for (uint32_t b = 0; b < v->bone_weights.size(); ++b) {
463				if (!std::isfinite(v->bone_weights[b].weight)) return {{v, describe_vertex(v) + " has bone_weights[" + std::to_string(b) + "].weight set to a non-finite value: " + std::to_string(v->bone_weights[b].weight) + "."}};
464			}
465		}
466	
467		for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
468			//NOTE: no edge data to check (both true and false are valid for sharp)
469		}
470	
471		for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
472			//NOTE: no edge data to check (both true and false are valid for boundary)
473		}
474	
475		for (HalfedgeCRef h = halfedges.begin(); h != halfedges.end(); ++h) {
476			if (!std::isfinite(h->corner_uv.x)) return {{h, describe_halfedge(h) + " has corner_uv.x set to a non-finite value: " + std::to_string(h->corner_uv.x) + "."}};
477			if (!std::isfinite(h->corner_uv.y)) return {{h, describe_halfedge(h) + " has corner_uv.y set to a non-finite value: " + std::to_string(h->corner_uv.y) + "."}};
478			if (!std::isfinite(h->corner_normal.x)) return {{h, describe_halfedge(h) + " has corner_normal.x set to a non-finite value: " + std::to_string(h->corner_normal.x) + "."}};
479			if (!std::isfinite(h->corner_normal.y)) return {{h, describe_halfedge(h) + " has corner_normal.y set to a non-finite value: " + std::to_string(h->corner_normal.y) + "."}};
480			if (!std::isfinite(h->corner_normal.z)) return {{h, describe_halfedge(h) + " has corner_normal.z set to a non-finite value: " + std::to_string(h->corner_normal.z) + "."}};
481		}
482	
483		//-----------------------------
484		//all references held by elements are to members of the vertices, edges, faces, or halfedges lists
485	
486		//for checking whether a reference is held in a given list:
487		std::unordered_set< Vertex const * > in_vertices = element_addresses(vertices);
488		std::unordered_set< Edge const * > in_edges = element_addresses(edges);
489		std::unordered_set< Face const * > in_faces = element_addresses(faces);
490		std::unordered_set< Halfedge const * > in_halfedges = element_addresses(halfedges);
491	
492		//helpers for describing things that aren't in the element lists:
493		std::unordered_set< Vertex const * > in_free_vertices = element_addresses(free_vertices);
494		std::unordered_set< Edge const * > in_free_edges = element_addresses(free_edges);
495		std::unordered_set< Face const * > in_free_faces = element_addresses(free_faces);
496		std::unordered_set< Halfedge const * > in_free_halfedges = element_addresses(free_halfedges);
497	
498		auto describe_missing_vertex = [this,&in_free_vertices](VertexCRef v) -> std::string {
499			if (v == vertices.end()) return "past-the-end vertex";
500			else if (in_free_vertices.count(&*v)) return "erased vertex with old id " + std::to_string(v->id & 0x7fffffffu);
501			else return "out-of-mesh vertex with address " + to_string(&*v);
502		};
503	
504		auto describe_missing_edge = [this,&in_free_edges](EdgeCRef e) -> std::string {
505			if (e == edges.end()) return "past-the-end edge";
506			else if (in_free_edges.count(&*e)) return "erased edge with old id " + std::to_string(e->id & 0x7fffffffu);
507			else return "out-of-mesh edge with address " + to_string(&*e);
508		};
509	
510		auto describe_missing_face = [this,&in_free_faces](FaceCRef f) -> std::string {
511			if (f == faces.end()) return "past-the-end face";
512			else if (in_free_faces.count(&*f)) return "erased face with old id " + std::to_string(f->id & 0x7fffffffu);
513			else return "out-of-mesh face with address " + to_string(&*f);
514		};
515	
516		auto describe_missing_halfedge = [this,&in_free_halfedges](HalfedgeCRef h) -> std::string {
517			if (h == halfedges.end()) return "past-the-end halfedge";
518			else if (in_free_halfedges.count(&*h)) return "erased halfedge with old id " + std::to_string(h->id & 0x7fffffffu);
519			else return "out-of-mesh halfedge with address " + to_string(&*h);
520		};
521	
522		//check references made by vertices:
523		for (VertexCRef v = vertices.begin(); v != vertices.end(); ++v) {
524			if (!in_halfedges.count(&*v->halfedge)) return {{v, describe_vertex(v) + " references " + describe_missing_halfedge(v->halfedge) + "."}};
525		}
526	
527		//check references made by edges:
528		for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
529			if (!in_halfedges.count(&*e->halfedge)) return {{e, describe_edge(e) + " references " + describe_missing_halfedge(e->halfedge) + "."}};
530		}
531	
532		//check references made by faces:
533		for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
534			if (!in_halfedges.count(&*f->halfedge)) return {{f, describe_face(f) + " references " + describe_missing_halfedge(f->halfedge) + "."}};
535		}
536	
537		//check references made by halfedges:
538		for (HalfedgeCRef h = halfedges.begin(); h != halfedges.end(); ++h) {
539			if (!in_halfedges.count(&*h->twin)) return {{h, describe_halfedge(h) + " has twin which references " + describe_missing_halfedge(h->twin) + "."}};
540			if (!in_halfedges.count(&*h->next)) return {{h, describe_halfedge(h) + " has next which references " + describe_missing_halfedge(h->next) + "."}};
541			if (!in_vertices.count(&*h->vertex)) return {{h, describe_halfedge(h) + " references " + describe_missing_vertex(h->vertex) + "."}};
542			if (!in_edges.count(&*h->edge)) return {{h, describe_halfedge(h) + " references " + describe_missing_edge(h->edge) + "."}};
543			if (!in_faces.count(&*h->face)) return {{h, describe_halfedge(h) + " references " + describe_missing_face(h->face) + "."}};
544		}
545	
546		//------------------------------
547		// - `edge->halfedge(->twin)^n` is a cycle of two halfedges
548		//   - this is also exactly the set of halfedges that reference `edge`
549		// - `face->halfedge(->next)^n` is a cycle of at least three halfedges
550		//   - this is also exactly the set of halfedges that reference `face`
551		// - `vertex->halfedge(->twin->next)^n` is a cycle of at least two halfedges
552		//   - this is also exactly the set of halfedges that reference `vertex`
553	
554		//first, build list of all halfedges that reference every other feature:
555		std::unordered_map< VertexCRef, std::unordered_set< HalfedgeCRef > > vertex_halfedges;
556		std::unordered_map< EdgeCRef, std::unordered_set< HalfedgeCRef > > edge_halfedges;
557		std::unordered_map< FaceCRef, std::unordered_set< HalfedgeCRef > > face_halfedges;
558		for (HalfedgeCRef h = halfedges.begin(); h != halfedges.end(); ++h) {
559			auto vret = vertex_halfedges[h->vertex].emplace(h);
560			assert(vret.second); //every halfedge is unique, so emplace can't fail
561			auto eret = edge_halfedges[h->edge].emplace(h);
562			assert(eret.second); //every halfedge is unique, so emplace can't fail
563			auto fret = face_halfedges[h->face].emplace(h);
564			assert(fret.second); //every halfedge is unique, so emplace can't fail
565		}
566	
567		//check edge->halfedge(->twin)^n:
568		for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
569			std::unordered_set< HalfedgeCRef > to_visit = edge_halfedges[e];
570			std::string path = "halfedge";
571			HalfedgeCRef h = e->halfedge;
572			do {
573				if (h->edge != e) return {{e, describe_edge(e) + " has " + path + " of " + describe_halfedge(h) + ", which does not reference the edge."}};
574				auto found = to_visit.find(h);
575				if (found == to_visit.end()) return {{e, describe_edge(e) + " has halfedge(->twin)^n which is not a cycle."}};
576				to_visit.erase(found);
577	
578				h = h->twin;
579				path += "->twin";
580			} while (h != e->halfedge);
581			if (!to_visit.empty()) return {{e, describe_edge(e) + " is referenced by " + describe_halfedge(*to_visit.begin()) + ", which is not in halfedge(->twin)^n."}};
582			if (edge_halfedges[e].size() != 2) return {{e, describe_edge(e) + " has " + std::to_string(edge_halfedges[e].size()) + " (!= 2) elements in its halfedge(->twin)^n cycle."}};
583		}
584	
585		//check face->halfedge(->next)^n:
586		for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
587			std::unordered_set< HalfedgeCRef > to_visit = face_halfedges[f];
588			std::string path = "halfedge";
589			HalfedgeCRef h = f->halfedge;
590			do {
591				if (h->face != f) return {{f, describe_face(f) + " has " + path + " of " + describe_halfedge(h) + ", which does not reference the face."}};
592				auto found = to_visit.find(h);
593				if (found == to_visit.end()) return {{f, describe_face(f) + " has halfedge(->next)^n which is not a cycle."}};
594				to_visit.erase(found);
595	
596				h = h->next;
597				path += "->next";
598			} while (h != f->halfedge);
599			if (!to_visit.empty()) return {{f, describe_face(f) + " is referenced by " + describe_halfedge(*to_visit.begin()) + ", which is not in halfedge(->next)^n."}};
600			if (face_halfedges[f].size() < 3) return {{f, describe_face(f) + " has " + std::to_string(face_halfedges[f].size()) + " (< 3) elements in its halfedge(->next)^n cycle."}};
601		}
602	
603		//check vertex->halfedge(->twin->next)^n:
604		for (VertexCRef v = vertices.begin(); v != vertices.end(); ++v) {
605			std::unordered_set< HalfedgeCRef > to_visit = vertex_halfedges[v];
606			std::string path = "halfedge";
607			HalfedgeCRef h = v->halfedge;
608			do {
609				if (h->vertex != v) return {{v, describe_vertex(v) + " has " + path + " of " + describe_halfedge(h) + ", which does not reference the vertex."}};
610				auto found = to_visit.find(h);
611				if (found == to_visit.end()) return {{v, describe_vertex(v) + " has halfedge(->twin->next)^n which is not a cycle."}};
612				to_visit.erase(found);
613	
614				h = h->twin->next;
615				path += "->twin->next";
616			} while (h != v->halfedge);
617			if (!to_visit.empty()) return {{v, describe_vertex(v) + " is referenced by " + describe_halfedge(*to_visit.begin()) + ", which is not in halfedge(->twin->next)^n."}};
618			if (vertex_halfedges[v].size() < 2) return {{v, describe_vertex(v) + " has " + std::to_string(vertex_halfedges[v].size()) + " (< 2) elements in its halfedge(->twin->next)^n cycle."}};
619		}
620	
621		//------------------------------
622		// - vertices are not orphaned (they have at least one non-boundary face adjacent)
623		// - vertices are on at most one boundary face
624	
625		for (VertexCRef v = vertices.begin(); v != vertices.end(); ++v) {
626			uint32_t non_boundary = 0;
627			uint32_t boundary = 0;
628			HalfedgeCRef h = v->halfedge;
629			do {
630				if (h->face->boundary) ++boundary;
631				else ++non_boundary;
632	
633				h = h->twin->next;
634			} while (h != v->halfedge);
635	
636			if (non_boundary == 0) return {{v, describe_vertex(v) + " is orphaned (has no adjacent non-boundary faces)."}};
637			if (boundary > 1) return {{v, describe_vertex(v) + " is on " + std::to_string(boundary) + " (> 1) boundary faces."}};
638		}
639	
640		//------------------------------
641		// - edges are not orphaned (they have at least one non-boundary face adjacent)
642		for (EdgeCRef e = edges.begin(); e != edges.end(); ++e) {
643			if (e->halfedge->face->boundary && e->halfedge->twin->face->boundary) return {{e, describe_edge(e) + " is orphaned (has no adjacent non-boundary face)."}};
644		}
645	
646	
647		//------------------------------
648		// - faces are simple (touch each vertex / edge at most once)
649		for (FaceCRef f = faces.begin(); f != faces.end(); ++f) {
650			std::unordered_set< VertexCRef > touched_vertices;
651			std::unordered_set< EdgeCRef > touched_edges;
652	
653			HalfedgeCRef h = f->halfedge;
654			do {
655				if (!touched_vertices.emplace(h->vertex).second) return {{f, describe_face(f) + " touches " + describe_vertex(h->vertex) + " more than once."}};
656				if (!touched_edges.emplace(h->edge).second) return {{f, describe_face(f) + " touches " + describe_edge(h->edge) + " more than once."}};
657	
658				h = h->next;
659			} while (h != f->halfedge);

659			} while (h != f->halfedge);
660		}
661	
662		return std::nullopt;
663	}
